def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    change = v2 - v1
    result = round(change)
    return {
        "value": result,
        "trace": {
            "v1": v1,
            "v2": v2,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "amount"
            }
        }
    }
